#!/usr/bin/env python3
"""Simple image web scraper.

Fetches a web page, extracts image URLs, and optionally downloads them.
The implementation intentionally uses only Python's standard library.
"""

from __future__ import annotations

import argparse
import json
import mimetypes
import re
import sys
from html.parser import HTMLParser
from pathlib import Path
from typing import Iterable, List
from urllib.error import HTTPError, URLError
from urllib.parse import urljoin, urlparse
from urllib.request import Request, urlopen

DEFAULT_USER_AGENT = "Mozilla/5.0 (compatible; ImageWebScraper/1.0)"
IMAGE_CANDIDATE_ATTRIBUTES = ("src", "data-src", "data-original", "data-lazy-src")


class ImageParser(HTMLParser):
    """Collect image references from HTML img tags."""

    def __init__(self, base_url: str) -> None:
        super().__init__()
        self.base_url = base_url
        self._seen: set[str] = set()
        self.image_urls: List[str] = []

    def handle_starttag(self, tag: str, attrs: list[tuple[str, str | None]]) -> None:
        if tag.lower() != "img":
            return

        attr_map = {key.lower(): value for key, value in attrs if value is not None}

        for attribute in IMAGE_CANDIDATE_ATTRIBUTES:
            value = attr_map.get(attribute)
            if value:
                self._add_url(value)
                break

        srcset = attr_map.get("srcset") or attr_map.get("data-srcset")
        if srcset:
            for candidate in parse_srcset(srcset):
                self._add_url(candidate)

    def _add_url(self, candidate: str) -> None:
        normalized = normalize_image_url(candidate, self.base_url)
        if not normalized or normalized in self._seen:
            return
        self._seen.add(normalized)
        self.image_urls.append(normalized)


def parse_srcset(srcset: str) -> list[str]:
    results: list[str] = []
    for part in srcset.split(","):
        candidate = part.strip().split()[0] if part.strip() else ""
        if candidate:
            results.append(candidate)
    return results


def normalize_image_url(raw_url: str, base_url: str) -> str | None:
    candidate = (raw_url or "").strip()
    if not candidate:
        return None
    if candidate.startswith("data:"):
        return None
    return urljoin(base_url, candidate)


def fetch_url(url: str, timeout: int = 15, user_agent: str = DEFAULT_USER_AGENT) -> bytes:
    request = Request(url, headers={"User-Agent": user_agent})
    with urlopen(request, timeout=timeout) as response:
        return response.read()


def fetch_html(url: str, timeout: int = 15, user_agent: str = DEFAULT_USER_AGENT) -> str:
    content = fetch_url(url, timeout=timeout, user_agent=user_agent)
    return content.decode("utf-8", errors="replace")


def scrape_image_urls(page_url: str, limit: int | None = None) -> list[str]:
    html = fetch_html(page_url)
    parser = ImageParser(page_url)
    parser.feed(html)
    parser.close()
    if limit is not None:
        return parser.image_urls[:limit]
    return parser.image_urls


def infer_filename(image_url: str, index: int, content_type: str | None = None) -> str:
    parsed = urlparse(image_url)
    raw_name = Path(parsed.path).name
    if raw_name and "." in raw_name:
        return sanitize_filename(raw_name)

    extension = None
    if content_type:
        extension = mimetypes.guess_extension(content_type.split(";")[0].strip())
    if not extension:
        extension = ".jpg"
    return f"image_{index:03d}{extension}"


def sanitize_filename(filename: str) -> str:
    sanitized = re.sub(r"[^A-Za-z0-9._-]", "_", filename)
    return sanitized or "image"


def download_image(
    image_url: str,
    output_dir: Path,
    index: int,
    timeout: int = 20,
    user_agent: str = DEFAULT_USER_AGENT,
) -> Path:
    request = Request(image_url, headers={"User-Agent": user_agent})
    with urlopen(request, timeout=timeout) as response:
        data = response.read()
        content_type = response.headers.get("Content-Type")

    filename = infer_filename(image_url, index, content_type)
    destination = make_unique_path(output_dir / filename)
    destination.write_bytes(data)
    return destination


def make_unique_path(path: Path) -> Path:
    if not path.exists():
        return path

    stem = path.stem
    suffix = path.suffix
    parent = path.parent
    counter = 1
    while True:
        candidate = parent / f"{stem}_{counter}{suffix}"
        if not candidate.exists():
            return candidate
        counter += 1


def write_manifest(output_dir: Path, page_url: str, image_urls: Iterable[str]) -> Path:
    manifest_path = output_dir / "images.json"
    payload = {
        "page_url": page_url,
        "image_count": len(list(image_urls)) if not isinstance(image_urls, list) else len(image_urls),
        "images": list(image_urls),
    }
    manifest_path.write_text(json.dumps(payload, indent=2), encoding="utf-8")
    return manifest_path


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(description="Scrape image URLs from a web page.")
    parser.add_argument("url", help="Page URL to scrape")
    parser.add_argument(
        "-o",
        "--output-dir",
        default="downloaded_images",
        help="Directory for downloaded images or manifest output",
    )
    parser.add_argument(
        "--limit",
        type=int,
        default=None,
        help="Maximum number of image URLs to return/download",
    )
    parser.add_argument(
        "--list-only",
        action="store_true",
        help="Print image URLs without downloading files",
    )
    parser.add_argument(
        "--manifest",
        action="store_true",
        help="Write scraped image URLs to images.json in the output directory",
    )
    return parser


def main(argv: list[str] | None = None) -> int:
    parser = build_parser()
    args = parser.parse_args(argv)

    try:
        image_urls = scrape_image_urls(args.url, limit=args.limit)
    except (HTTPError, URLError, ValueError) as exc:
        print(f"Error while scraping {args.url}: {exc}", file=sys.stderr)
        return 1

    if not image_urls:
        print("No images found.")
        return 0

    output_dir = Path(args.output_dir)

    if args.list_only:
        for image_url in image_urls:
            print(image_url)
        if args.manifest:
            output_dir.mkdir(parents=True, exist_ok=True)
            manifest_path = write_manifest(output_dir, args.url, image_urls)
            print(f"Wrote manifest: {manifest_path}")
        return 0

    output_dir.mkdir(parents=True, exist_ok=True)

    if args.manifest:
        manifest_path = write_manifest(output_dir, args.url, image_urls)
        print(f"Wrote manifest: {manifest_path}")

    for index, image_url in enumerate(image_urls, start=1):
        try:
            saved_path = download_image(image_url, output_dir, index=index)
            print(f"Downloaded {image_url} -> {saved_path}")
        except (HTTPError, URLError, OSError, ValueError) as exc:
            print(f"Failed to download {image_url}: {exc}", file=sys.stderr)

    return 0


if __name__ == "__main__":
    raise SystemExit(main())
